101	Add new read-only properties to `ViewTexts/DiffDialogTexts.cs` for each new locale key added in Step 1. Each property follows the existing pattern:
102	
103	```csharp
104	public string GuidanceSidebarTitle => _localization.GetString("DiffDialog", "GuidanceSidebarTitle");
105	```
106	
107	Add all new property names to the `OnCultureChanged()` handler to ensure they refresh on language switch.
108	
109	### Step 4: Add Sidebar Brush Resources
110	
111	Add the following brush resources to `Styles/DiffBrushes.xaml`:
112	
113	```xml
114	<!-- Sidebar guidance card backgrounds -->
115	<SolidColorBrush x:Key="DiffBrush.GuidanceRemovalBackground" Color="#33F44336" />
116	<SolidColorBrush x:Key="DiffBrush.GuidanceInsertionBackground" Color="#33FF9800" />
117	<SolidColorBrush x:Key="DiffBrush.GuidanceReplacementBackground" Color="#339C27B0" />
118	<SolidColorBrush x:Key="DiffBrush.GuidanceAddedBackground" Color="#334CAF50" />
119	<SolidColorBrush x:Key="DiffBrush.GuidanceSidebarBackground" Color="#0AFFFFFF" />
120	```
121	
122	These use 20% alpha versions of the same base colors as the existing diff row brushes, providing visual consistency between the diff list and the sidebar.
123	
124	### Step 5: Add Computed Properties to DiffDialogViewModel
125	
126	Add the following computed properties to `ViewModels/DiffDialogViewModel.cs`:
127	
128	```csharp
129	// Change type counts
130	public int RemovedModCount => DiffLines.Count(l => l.ChangeType == DiffChangeType.Removed);
131	public int InsertedModCount => DiffLines.Count(l => l.ChangeType == DiffChangeType.Inserted);
132	public int ReplacedModCount => DiffLines.Count(l => l.ChangeType == DiffChangeType.Replaced);
133	public int AddedModCount => DiffLines.Count(l => l.ChangeType == DiffChangeType.Added);
134	
135	// Sidebar card visibility (sidebar container has no visibility binding — it is always rendered)
136	public bool HasRemovedMods => RemovedModCount > 0;
137	public bool ShowRemovalGuidance => HasDifferences && HasRemovedMods;
138	public bool ShowInsertionGuidance => HasDifferences && HasInsertedMods;
139	public bool ShowReplacementGuidance => HasDifferences && ReplacedModCount > 0;
140	public bool ShowAddedGuidance => HasDifferences && HasAddedMods;
141	public bool ShowNoChangesGuidance => !HasDifferences;
142	
143	// Count display strings (singular/plural)
144	public string RemovedModCountText => RemovedModCount == 1
145	    ? Texts.GuidanceRemovalCountSingular
146	    : string.Format(Texts.GuidanceRemovalCountFormat, RemovedModCount);
147	public string InsertedModCountText => InsertedModCount == 1
148	    ? Texts.GuidanceInsertionCountSingular
149	    : string.Format(Texts.GuidanceInsertionCountFormat, InsertedModCount);
150	public string ReplacedModCountText => ReplacedModCount == 1
151	    ? Texts.GuidanceReplacementCountSingular
152	    : string.Format(Texts.GuidanceReplacementCountFormat, ReplacedModCount);
153	public string AddedModCountText => AddedModCount == 1
154	    ? Texts.GuidanceAddedCountSingular
155	    : string.Format(Texts.GuidanceAddedCountFormat, AddedModCount);
156	
157	// Pass-through text properties for sidebar card headings and body text
158	// (DiffWindow.xaml binds to VM properties, not Texts.* sub-paths — consistent with existing bindings)
159	public string GuidanceSidebarTitle => Texts.GuidanceSidebarTitle;
160	public string GuidanceRemovalTitle => Texts.GuidanceRemovalTitle;
161	public string GuidanceRemovalBody => Texts.GuidanceRemovalBody;
162	public string GuidanceInsertionTitle => Texts.GuidanceInsertionTitle;
163	public string GuidanceInsertionBody => Texts.GuidanceInsertionBody;
164	public string GuidanceReplacementTitle => Texts.GuidanceReplacementTitle;
165	public string GuidanceReplacementBody => Texts.GuidanceReplacementBody;
166	public string GuidanceAddedTitle => Texts.GuidanceAddedTitle;
167	public string GuidanceAddedBody => Texts.GuidanceAddedBody;
168	public string GuidanceNoChangesTitle => Texts.GuidanceNoChangesTitle;
169	public string GuidanceNoChangesBody => Texts.GuidanceNoChangesBody;
170	
171	// Tooltip pass-through properties for PackIcon bindings (Added, Removed, Replaced, Moved only)
172	public string AddedTooltip => Texts.AddedTooltip;
173	public string RemovedTooltip => Texts.RemovedTooltip;
174	public string ReplacedTooltip => Texts.ReplacedTooltip;
175	public string MovedTooltip => Texts.MovedTooltip;
176	```
177	
178	Add `OnPropertyChanged` calls for all new properties in `UpdateDiffState()`.
179	
180	### Step 6: Restructure DiffWindow XAML Layout
181	
182	Modify `Views/DiffWindow.xaml` to wrap the existing content area in a two-column layout. The key structural change:
183	
184	1. **Increase default window size**: Change `Width="810"` to `Width="1060"` and `MinWidth="480"` to `MinWidth="720"`.
185	
186	2. **Insert a Grid with two columns** at the level where Grid.Row="2" (the diff ListView) currently sits. The left column gets the diff ListView (star-sized), and the right column gets the recommendations sidebar (fixed width ~260px).
187	
188	3. The two-column Grid replaces the current single Border+ListView in Row 2. All rows above (description, checkbox) and below (sorting banner, status, buttons) remain unchanged.
189	
190	Structural outline of the modified Row 2:
191	
192	```xml
193	<Grid Grid.Row="2">
194	    <Grid.ColumnDefinitions>
195	        <ColumnDefinition Width="*" />        <!-- Diff list -->
196	        <ColumnDefinition Width="260" />      <!-- Sidebar -->
197	    </Grid.ColumnDefinitions>
198	
199	    <!-- Existing diff ListView in Column 0 -->

